  "node.ssh.firewallHint": "После успешного SSH панель добавит SSH TCP-порт, TCP 80/443 и UDP 443 в уже активный UFW или firewalld. Неактивный firewall останется выключенным. Когда агент применит включённый UDP-профиль, он синхронизирует точный порт и принятый диапазон Hysteria2 в активный UFW. Эти входящие правила для firewalld нужно вручную добавить в активную зону. Firewall хостера настраивается отдельно.",
  "node.ssh.error.systemd": "Mistgate не смог установить или запустить службу systemd. Проверь сервер перед повтором.",
