  "node.check.decoy.tls": "{node} 上的 TCP {port} 转给了「{vless}」。在此期间「{hy2}」的站点处于关闭状态，端口空闲后恢复；这段时间 TCP {port} 只返回普通的 404。证书仍会通过「{vless}」续期。",
