  "node.check.decoy.port80.busy": "节点上另有程序占用了端口 80，因此 Hysteria2 证书将无法续期。请释放节点上的 80 端口（诊断会指出是哪个程序），把「{vless}」改到 8443，或将其 REALITY 目标设为「本节点站点」。",
