  "node.ssh.error.timeout": "پنل به‌موقع به این آدرس و پورت SSH نرسید. بررسی کن SSH در حال اجرا باشد و در فایروال یا security group سرویس‌دهنده، TCP ورودی از IP خروجی عمومی سرور پنل را مجاز کن. اگر فایروال خود سرور جلوی SSH را گرفته، اول از کنسول سرویس‌دهنده یا دسترسی بازیابی بازش کن. پنل فقط بعد از برقراری اتصال SSH می‌تواند قانون‌های سرور را آماده کند؛ قانون‌های سرویس‌دهنده را باید در تنظیمات خود سرویس‌دهنده عوض کرد.",
  "node.ssh.error.timeoutEdge": "پنل به‌موقع از این آدرس و پورت SSH پاسخی نگرفت. نسخهٔ Cloudflare از شبکهٔ Cloudflare وصل می‌شود، نه از کامپیوتر تو؛ پس SSH باید TCP ورودی را از اینترنت بپذیرد (هم فایروال سرویس‌دهنده، هم فایروال سرور)، نه فقط از IP خودت. آن را برای مدت نصب باز کن یا از دستور دستی استفاده کن.",
  "node.ssh.error.refused": "شبکهٔ پنل این آدرس را نپذیرفت، یا سرور از آن شبکه در دسترس نیست. نسخهٔ Cloudflare از شبکهٔ Cloudflare وصل می‌شود: آدرس‌های Cloudflare، نام‌های پشت پراکسی Cloudflare (ابر نارنجی) و شبکه‌های خصوصی یا فقط\u200E-VPN پذیرفته نمی‌شوند. آدرس عمومی خود سرور را وارد کن یا نود را با دستور دستی نصب کن.",
  "node.ssh.useManual": "استفاده از دستور دستی",
