  "node.ssh.error.panelAddress": "آدرس عمومی پنل تنظیم نشده است، برای همین نود نمی‌تواند دوباره به آن وصل شود.",
  "node.ssh.error.panelUnreachable": "سرور نتوانست یک اتصال TCP به آدرس ایجنت‌های پنل باز کند. آن را در فایروال یا security group جلوی پنل مجاز کن، بررسی کن سرور اجازهٔ اتصال خروجی دارد و دوباره امتحان کن.",
