  "node.ssh.error.identity": "روی سرور از قبل هویت یک نود دیگر یا هویت خراب‌شدهٔ نود Mistgate هست (\u200E/var/lib/mistgate-node). این پوشه را فقط اگر آن نود دیگر وجود ندارد روی سرور پاک کن و دوباره امتحان کن.",
  "node.ssh.error.bundle": "پنل برای معماری این سرور ایجنت معتبری ندارد. «بستهٔ ریلیز» را در صفحهٔ «به‌روزرسانی‌ها» بررسی کن و دوباره امتحان کن.",
