  "node.ssh.error.remoteOutcome": "SSH بعد از ایجاد تغییرهایی روی سرور قطع شد. شاید بخشی از دستورهای نصب اجرا شده باشد؛ پیش از تلاش دوباره سرور را بررسی کن.",
  "node.ssh.error.firewall": "پنل وصل شد، اما نتوانست قانون‌های فعال UFW/firewalld را روی سرور آماده کند. دسترسی root یا sudo بدون رمز حساب SSH را بررسی کن و پیش از تلاش دوباره فایروال سرور را ببین. قانون‌های فایروال سرویس‌دهنده جداگانه مدیریت می‌شوند.",
  "node.ssh.error.retired": "این نود وسط نصب از رده خارج شد. برای ساخت رکورد نود جدید، نصب تازه‌ای شروع کن.",
  "node.ssh.error.notConnected": "ایجنت نصب شد اما به پنل وصل نشد. آدرس پنل و دسترسی خروجی نود را بررسی کن.",
  "node.ssh.firewallHint": "بعد از موفقیت SSH، پنل پورت TCP مربوط به SSH، پورت‌های TCP 80/443 و UDP 443 را به UFW یا firewalld که از قبل فعال است اضافه می‌کند. فایروالِ غیرفعال همان‌طور غیرفعال می‌ماند. وقتی ایجنت یک ورودی UDP فعال را اعمال می‌کند، پورت دقیق شنودکننده و بازهٔ پرش پذیرفته‌شدهٔ Hysteria2 را در UFW فعال همگام می‌کند. همین قانون‌های ورودی را خودت باید در ناحیهٔ فعال firewalld اضافه کنی. قانون‌های فایروال سرویس‌دهنده جداست.",
  "node.ssh.error.systemd": "Mistgate نتوانست سرویس systemd خودش را نصب یا راه‌اندازی کند. پیش از تلاش دوباره سرور را بررسی کن.",
