  "node.ssh.error.timeout": "Panel bu SSH adresine ve portuna zamanında ulaşamadı. SSH'ın çalıştığını kontrol et ve sağlayıcının güvenlik duvarında ya da güvenlik grubunda, panel sunucusunun herkese açık çıkış IP'sinden gelen TCP'ye izin ver. Sunucunun kendi güvenlik duvarı SSH'ı engelliyorsa önce sağlayıcının konsolundan ya da kurtarma erişiminden aç. Panel, hedef sunucunun güvenlik duvarı kurallarını yalnızca SSH bağlandıktan sonra hazırlayabilir; sağlayıcı kurallarını sağlayıcının ayarlarından değiştirmen gerekir.",
  "node.ssh.error.timeoutEdge": "Panel bu SSH adresinden ve portundan zamanında yanıt alamadı. Cloudflare sürümü senin bilgisayarından değil, Cloudflare ağından bağlanır; bu yüzden SSH yalnızca senin IP'nden değil, internetten gelen TCP'yi de kabul etmeli (hem sağlayıcının hem sunucunun güvenlik duvarında). Kurulum için aç ya da düğümü komutla elle kur.",
  "node.ssh.error.refused": "Panelin ağı bu adresle bağlantıyı reddetti ya da sunucuya oradan ulaşılamıyor. Cloudflare sürümü Cloudflare ağından bağlanır: Cloudflare adresleri, Cloudflare proxy'sinin (turuncu bulut) arkasındaki adlar ve özel ya da yalnızca VPN'e açık ağlar reddedilir. Sunucunun kendi herkese açık adresini gir ya da düğümü komutla elle kur.",
  "node.ssh.useManual": "Komutla elle kur",
